handler:
router.patch(
    '/:id/tags/:tagId',
    authenticate,
    authorize(...curateRoles),
    validateParams(tagParamsSchema),
    validateBody(renameTagSchema),
    logRequest({}),
    async (req: Request, res: Response) => {
      const comingFrom = `module/brand/tags/api.ts - /:id/tags/:tagId`;
